    h,w=len(grid),len(grid[0])
    # Locate the monochrome barrier and move each connected object toward it.
    rowwall=next((r for r in range(h) if grid[r][0] != 0 and len(set(grid[r]))==1),None)
    colwall=next((c for c in range(w) if grid[0][c] != 0 and all(row[c]==grid[0][c] for row in grid)),None)
    vertical=rowwall is not None
    wall=rowwall if vertical else colwall
    wc=grid[wall][0] if vertical else grid[0][wall]
    dr=-1 if vertical and rowwall==0 else (1 if vertical else 0)
    dc=-1 if not vertical and colwall==0 else (1 if not vertical else 0)
    out=[[0]*w for _ in range(h)]
    if vertical:
        out[wall]=grid[wall][:]
    else:
        for r in range(h): out[r][wall]=wc
    seen=set(); pieces=[]
    for r in range(h):
      for c in range(w):
        v=grid[r][c]
        if v==0 or (r,c) in seen or (vertical and r==wall) or (not vertical and c==wall):
          continue
        stack=[(r,c)]; seen.add((r,c)); cells=[]
        while stack:
          x,y=stack.pop(); cells.append((x,y))
          for nx,ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
            if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and grid[nx][ny]==v:
              seen.add((nx,ny)); stack.append((nx,ny))
        pieces.append((cells,v))
    if vertical:
      pieces.sort(key=lambda p: min(r for r,c in p[0]) if dr==-1 else -max(r for r,c in p[0]))
    else:
      pieces.sort(key=lambda p: min(c for r,c in p[0]) if dc==-1 else -max(c for r,c in p[0]))
    for cells,v in pieces:
      while True:
        moved=[(r+dr,c+dc) for r,c in cells]
        if any(r<0 or r>=h or c<0 or c>=w or out[r][c] for r,c in moved): break
        cells=moved
      for r,c in cells: out[r][c]=v
    return out
